import fs from 'node:fs';
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
const {chromium}=createRequire(new URL('../../web/package.json',import.meta.url))('playwright-core');
const dir='docs/research/photo-multisource-20261107',cache='.logs/photo-multisource-20261107',read=f=>JSON.parse(fs.readFileSync(f,'utf8')),save=(f,v)=>fs.writeFileSync(f,JSON.stringify(v,null,2)+'\n');
const env=fs.readFileSync('.env.local','utf8'),key=process.env.UNSPLASH_ACCESS_KEY||env.split(/\r?\n/).find(l=>l.startsWith('UNSPLASH_ACCESS_KEY='))?.slice('UNSPLASH_ACCESS_KEY='.length).trim();assert(key,'Existing Unsplash configuration missing');
const addUtm=s=>{const u=new URL(s);u.searchParams.set('utm_source','wander');u.searchParams.set('utm_medium','referral');return u.href;};
const files=fs.readdirSync('backend/src/main/resources/catalog').filter(f=>f.endsWith('.json')),cats=files.map(file=>({file,data:read('backend/src/main/resources/catalog/'+file)})),places=cats.flatMap(d=>d.data.places);
if(process.argv[2]==='review'){
 const picked=[['AoYyfTvZUTI','Banyan Tree Lang Co Vietnam'],['tOCa0lSuS3M','Premier Village Phu Quoc Resort - Managed by Accor']],candidates=[];
 for(const [id,name]of picked){const place=places.find(p=>p.name===name);assert(place,name);const res=await fetch('https://api.unsplash.com/photos/'+id,{headers:{Authorization:'Client-ID '+key,'Accept-Version':'v1'},signal:AbortSignal.timeout(20000)});assert(res.ok,'Unsplash metadata HTTP '+res.status);const p=await res.json();assert(p.id===id&&p.user.name&&p.user.links.html&&p.links.download_location);save(cache+'/sources/unsplash-'+id+'.json',p);candidates.push({id,placeId:place.id,name,description:p.description,alt:p.alt_description,author:p.user.name,authorUrl:addUtm(p.user.links.html),sourceUrl:addUtm(p.links.html),url:p.urls.regular,downloadLocation:p.links.download_location,license:'Unsplash',status:'PENDING_VISUAL_REVIEW'});}
 save(dir+'/unsplash-shortlist.json',candidates);const browser=await chromium.launch({channel:'chrome',headless:true});try{const page=await browser.newPage({viewport:{width:1400,height:900}});await page.setContent('<style>body{font:16px system-ui}main{display:flex;gap:20px}figure{flex:1}img{width:100%;height:450px;object-fit:contain}</style><main>'+candidates.map(p=>'<figure><img src="'+p.url.replaceAll('&','&amp;')+'"><figcaption>'+p.name+'<br>'+p.description+'<br>'+p.author+'</figcaption></figure>').join('')+'</main>');await page.waitForFunction(()=>[...document.images].every(i=>i.complete&&i.naturalWidth>0));await page.screenshot({path:cache+'/unsplash-selected-review.png',fullPage:true});}finally{await browser.close();}console.log(JSON.stringify({candidates:candidates.length}));
}
if(process.argv[2]==='apply'){
 const candidates=read(dir+'/unsplash-shortlist.json'),selections=read(dir+'/unsplash-reviewed.json'),trackingFile=dir+'/unsplash-download-tracking.json',tracking=fs.existsSync(trackingFile)?read(trackingFile):{},approved=[];
 for(const s of selections){const p=candidates.find(p=>p.id===s.id);assert(p&&s.note);if(!tracking[p.id]){const res=await fetch(p.downloadLocation,{headers:{Authorization:'Client-ID '+key,'Accept-Version':'v1'},signal:AbortSignal.timeout(20000)});assert(res.ok,'Unsplash download tracking HTTP '+res.status);await res.json();tracking[p.id]={trackedAt:new Date().toISOString(),status:res.status};save(trackingFile,tracking);}
  const target=places.find(x=>x.id===p.placeId);assert(target);const photo={url:p.url,author:p.author,authorUrl:p.authorUrl,license:p.license,sourceUrl:p.sourceUrl,...(s.caption?{caption:s.caption}:{})};if(!target.photos.some(ph=>ph.url===p.url))target.photos.push(photo);approved.push({...p,status:'APPROVED',photo,reviewNote:s.note,trackedAt:tracking[p.id].trackedAt});}
 for(const {file,data}of cats)save('backend/src/main/resources/catalog/'+file,data);save(dir+'/unsplash-approved.json',approved);console.log(JSON.stringify({appliedUnsplashPhotos:approved.length}));
}
